using NUnit.Framework;
using {project_name}.Core;

namespace {project_name}.Tests.EditMode
{
    public class CoreMathTests
    {
        [Test]
        public void Clamp_ValueWithinRange_ReturnsValue()
        {
            float result = CoreMath.Clamp(5f, 0f, 10f);
            Assert.AreEqual(5f, result, 0.001f);
        }

        [Test]
        public void SafeDivide_DivideByZero_ReturnsFallback()
        {
            float result = CoreMath.SafeDivide(10f, 0f, 42f);
            Assert.AreEqual(42f, result, 0.001f);
        }
    }
}
